Looking at the current code, I need to identify loops where unrolling can provide parallelism benefits:

1. **`mean_acc_j` loop** (inner feature loop): accumulates mean across M features - can unroll
2. **`center_j` loop**: centers data across M features - can unroll  
3. **`cov_j` loop**: covariance accumulation inner loop - can unroll
4. **Load/store inner loops**: can benefit from unrolling to enable parallel memory access

The key insight is:
- `local_tile` is partitioned cyclic factor=8 on dim=2 (the M dimension)
- `local_mean` is complete partitioned
- `local_cov` is partitioned cyclic factor=8 on dim=2

I'll add `#pragma HLS UNROLL factor=8` to the inner `j` loops that iterate over the M dimension, matching the existing array partitioning factor of 8. I'll also increase partitioning on `local_tile` and `local_cov` to factor=8 (already done) to ensure no bank conflicts.

```cpp
#include "covariance.h"
#include <string.h>

// Tile size for the N (row) dimension
#define TILE_N 16

// ---------------------------------------------------------------------------
// Load a tile of rows [row_start, row_start+TILE_N) from global data
// into local_tile[TILE_N][M]
// ---------------------------------------------------------------------------
static void load_data_tile(
    double data[N][M],
    double local_tile[TILE_N][M],
    int row_start,
    int tile_rows)
{
    for (int i = 0; i < tile_rows; i++) {
        for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
            local_tile[i][j] = data[row_start + i][j];
        }
    }
}

// ---------------------------------------------------------------------------
// Store a tile of rows back to global data
// ---------------------------------------------------------------------------
static void store_data_tile(
    double data[N][M],
    double local_tile[TILE_N][M],
    int row_start,
    int tile_rows)
{
    for (int i = 0; i < tile_rows; i++) {
        for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
            data[row_start + i][j] = local_tile[i][j];
        }
    }
}

// ---------------------------------------------------------------------------
// Compute mean: accumulate contributions from one tile of rows
// ---------------------------------------------------------------------------
static void compute_mean_tile(
    double local_tile[TILE_N][M],
    double local_mean[M],
    int tile_rows,
    bool init)
{
    for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
        if (init) local_mean[j] = 0.0;
    }
    for (int i = 0; i < tile_rows; i++) {
        for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
            local_mean[j] += local_tile[i][j];
        }
    }
}

// ---------------------------------------------------------------------------
// Center data tile: subtract mean from each element in the tile
// ---------------------------------------------------------------------------
static void compute_center_tile(
    double local_tile[TILE_N][M],
    double local_mean[M],
    int tile_rows)
{
    for (int i = 0; i < tile_rows; i++) {
        for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
            local_tile[i][j] -= local_mean[j];
        }
    }
}

// ---------------------------------------------------------------------------
// Accumulate covariance contributions from one centered tile
// partial_cov[i][j] += sum_k_in_tile( tile[k][i] * tile[k][j] )
// ---------------------------------------------------------------------------
static void compute_cov_tile(
    double local_tile[TILE_N][M],
    double partial_cov[M][M],
    int tile_rows,
    bool init)
{
    if (init) {
        for (int i = 0; i < M; i++) {
            for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
                partial_cov[i][j] = 0.0;
            }
        }
    }
    for (int k = 0; k < tile_rows; k++) {
        for (int i = 0; i < M; i++) {
            for (int j = i; j < M; j++) {
#pragma HLS PIPELINE II=1
                partial_cov[i][j] += local_tile[k][i] * local_tile[k][j];
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Store mean to global memory
// ---------------------------------------------------------------------------
static void store_mean(double mean[M], double local_mean[M])
{
    for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
        mean[j] = local_mean[j];
    }
}

// ---------------------------------------------------------------------------
// Store covariance (symmetrize and scale) to global memory
// ---------------------------------------------------------------------------
static void store_cov(double cov[M][M], double partial_cov[M][M], double float_n)
{
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
            double val = partial_cov[i][j] / (float_n - 1.0);
            // partial_cov was only filled for j >= i; mirror symmetrically
            cov[i][j] = (j >= i) ? val : partial_cov[j][i] / (float_n - 1.0);
        }
    }
}

