#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
#pragma HLS LOOP_TRIPCOUNT min=1 max=M
#pragma HLS DEPENDENCE variable=local_cov inter false
                    local_cov[i][j] += local_tile[k][i] * local_tile[k][j];
