// ===========================================================================
// Helper: read M doubles from wide bus into local array
// base: wide bus pointer, byte_offset: byte offset into base, dst: output
// ===========================================================================
static void wide_read_doubles(double* dst, const ap_uint<512>* base, int byte_offset, int count) {
#pragma HLS INLINE
    // Each ap_uint<512> word holds 8 doubles (512/64=8)
    int word_start = byte_offset / 64; // 64 bytes per word
    int elem_start = (byte_offset % 64) / 8; // which double within word
    int done = 0;
    int word_idx = word_start;
    int elem_idx = elem_start;
    read_loop: while (done < count) {
#pragma HLS PIPELINE II=1
        ap_uint<512> word = base[word_idx];
        int pos = elem_idx * 64;
        ap_uint<64> bits = word.range(pos + 63, pos);
        double val;
        memcpy(&val, &bits, sizeof(double));
        dst[done] = val;
        done++;
        elem_idx++;
        if (elem_idx == DOUBLES_PER_WORD) {
            elem_idx = 0;
            word_idx++;
        }
    }
}

// ===========================================================================
// Helper: write M doubles from local array to wide bus
// ===========================================================================
static void wide_write_doubles(ap_uint<512>* base, const double* src, int byte_offset, int count) {
#pragma HLS INLINE
    int word_start = byte_offset / 64;
    int elem_start = (byte_offset % 64) / 8;
    int done = 0;
    int word_idx = word_start;
    int elem_idx = elem_start;
