    // Use a local word buffer
    ap_uint<512> word = (elem_start != 0) ? base[word_idx] : ap_uint<512>(0);
    write_loop: while (done < count) {
#pragma HLS PIPELINE II=1
        double val = src[done];
        ap_uint<64> bits;
        memcpy(&bits, &val, sizeof(double));
        int pos = elem_idx * 64;
        word.range(pos + 63, pos) = bits;
        elem_idx++;
        done++;
        if (elem_idx == DOUBLES_PER_WORD) {
            base[word_idx] = word;
            word_idx++;
            word = (done < count) ? base[word_idx] : ap_uint<512>(0);
            elem_idx = 0;
        }
    }
    // flush remaining partial word
    if (elem_idx != 0) {
        base[word_idx] = word;
    }
